package com.primehr.succession.domain;
import com.primehr.rsp.domain.RspAuditedEntity; import jakarta.persistence.*; import java.util.Locale;
@Entity @Table(name="succession_readiness_level",uniqueConstraints={@UniqueConstraint(name="uk_succ_level_code",columnNames={"agency_id","scale_version_id","normalized_code"}),@UniqueConstraint(name="uk_succ_level_order",columnNames={"agency_id","scale_version_id","display_order"})})
public class SuccessionReadinessLevel extends RspAuditedEntity {
 @Column(name="scale_version_id",nullable=false,length=36) private String scaleVersionId; @Column(nullable=false,length=80) private String code; @Column(name="normalized_code",nullable=false,length=80) private String normalizedCode; @Column(nullable=false,length=200) private String label; @Column(nullable=false,length=2000) private String description; @Column(name="development_guidance",nullable=false,length=4000) private String developmentGuidance; @Column(name="review_after_months") private Integer reviewAfterMonths; @Column(name="allows_pool_membership",nullable=false) private boolean allowsPoolMembership; @Column(name="display_order",nullable=false) private int displayOrder;
 protected SuccessionReadinessLevel(){}
 public SuccessionReadinessLevel(String agencyId,String scaleVersionId,String code,String label,String description,String guidance,Integer reviewMonths,boolean allows,int order){super(agencyId);this.scaleVersionId=requiredText(scaleVersionId,"scaleVersionId");this.code=requiredText(code,"code");normalizedCode=this.code.toUpperCase(Locale.ROOT);this.label=requiredText(label,"label");this.description=requiredText(description,"description");developmentGuidance=requiredText(guidance,"developmentGuidance");if(reviewMonths!=null&&reviewMonths<1)throw new IllegalArgumentException("reviewAfterMonths must be positive");if(order<1)throw new IllegalArgumentException("displayOrder must be positive");reviewAfterMonths=reviewMonths;allowsPoolMembership=allows;displayOrder=order;}
 public String getScaleVersionId(){return scaleVersionId;} public String getCode(){return code;} public String getLabel(){return label;} public String getDescription(){return description;} public String getDevelopmentGuidance(){return developmentGuidance;} public Integer getReviewAfterMonths(){return reviewAfterMonths;} public boolean isAllowsPoolMembership(){return allowsPoolMembership;} public int getDisplayOrder(){return displayOrder;}
}
